#!/usr/bin/env python3
"""A minimal DNS server for testing dog. Logs query hex, responds with canned packets."""
import socket, struct, sys, binascii

def name_to_wire(name):
    out = b''
    for part in name.split('.'):
        if part:
            out += bytes([len(part)]) + part.encode()
    return out + b'\x00'

def build_response(query, answers=None, rcode=0, aa=False, tc=False, rd=None, ra=True, ad=False, cd=False,
                   authorities=None, additionals=None, qdcount=1, extra_question=None, opcode=0):
    tid, flags, qd, an, ns, ar = struct.unpack('>HHHHHH', query[:12])
    # find end of question section
    offset = 12
    questions = query[12:]
    # parse qd questions to find end
    for _ in range(qd):
        while True:
            l = query[offset]
            if l == 0:
                offset += 1
                break
            if l & 0xC0 == 0xC0:
                offset += 2
                break
            offset += 1 + l
        offset += 4
    question = query[12:offset]
    newflags = 0x8000 | (opcode << 11)
    if aa: newflags |= 0x0400
    if tc: newflags |= 0x0200
    if rd is None:
        rd = bool(flags & 0x0100)
    if rd: newflags |= 0x0100
    if ra: newflags |= 0x0080
    if ad: newflags |= 0x0020
    if cd: newflags |= 0x0010
    newflags |= rcode & 0xF
    answers = answers or []
    authorities = authorities or []
    additionals = additionals or []
    hdr = struct.pack('>HHHHHH', tid, newflags, qd, len(answers), len(authorities), len(additionals))
    return hdr + question + b''.join(answers + authorities + additionals)

def rr(name, rtype, rclass, ttl, rdata):
    return name_to_wire(name) + struct.pack('>HHIH', rtype, rclass, ttl, len(rdata)) + rdata

def rr_at(ptr, rtype, rclass, ttl, rdata):
    # compression pointer to offset 0x0c (question name)
    return struct.pack('>H', 0xC000 | ptr) + struct.pack('>HHIH', rtype, rclass, ttl, len(rdata)) + rdata

A = lambda ip: socket.inet_aton(ip)
AAAA = lambda ip: socket.inet_pton(socket.AF_INET6, ip)

def serve(port=15353, mode='a'):
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.bind(('127.0.0.1', port))
    print(f"listening on {port} mode={mode}", file=sys.stderr)
    while True:
        data, addr = sock.recvfrom(4096)
        print("QUERY: " + binascii.hexlify(data).decode(), file=sys.stderr)
        resp = build(data, mode)
        if resp is not None:
            sock.sendto(resp, addr)

def build(data, mode):
    qname_end = data.index(b'\x00', 12)
    qname_wire = data[12:qname_end+1]
    qtype, qclass = struct.unpack('>HH', data[qname_end+1:qname_end+5])
    # decode qname
    parts = []
    i = 12
    while data[i]:
        l = data[i]
        parts.append(data[i+1:i+1+l].decode())
        i += 1+l
    qname = '.'.join(parts)
    ptr = 0x0c
    if mode == 'a':
        ans = [rr_at(ptr, 1, 1, 300, A('93.184.216.34'))]
        return build_response(data, answers=ans)
    if mode == 'multi':
        ans = [rr_at(ptr, 1, 1, 300, A('93.184.216.34')),
               rr_at(ptr, 1, 1, 3600, A('1.2.3.4'))]
        return build_response(data, answers=ans)
    if mode == 'echo-type':
        # respond with record of the queried type with generic rdata
        rdata_map = {
            1: A('93.184.216.34'),
            2: name_to_wire('ns1.example.net'),
            5: name_to_wire('alias.example.net'),
            15: struct.pack('>H', 10) + name_to_wire('mail.example.net'),
            16: b'\x05hello\x05world',
            28: AAAA('2606:2800:220:1:248:1893:25c8:1946'),
            12: name_to_wire('ptr.example.net'),
            6: name_to_wire('ns.example.net') + name_to_wire('hostmaster.example.net') + struct.pack('>IIIII', 2024010101, 7200, 3600, 1209600, 300),
            33: struct.pack('>HHH', 1, 5, 8080) + name_to_wire('sip.example.net'),
        }
        rdata = rdata_map.get(qtype, bytes(range(1, 17)))
        ans = [rr_at(ptr, qtype, 1, 300, rdata)]
        return build_response(data, answers=ans)
    if mode == 'nxdomain':
        return build_response(data, rcode=3)
    if mode == 'servfail':
        return build_response(data, rcode=2)
    if mode == 'tc':
        return build_response(data, tc=True)
    if mode == 'empty':
        return build_response(data)
    if mode == 'none':
        return None
    raise ValueError(mode)

if __name__ == '__main__':
    mode = sys.argv[1] if len(sys.argv) > 1 else 'a'
    port = int(sys.argv[2]) if len(sys.argv) > 2 else 15353
    serve(port, mode)

