            46: b'\x01\x02' + A('10.20.30.40'),  # SSHFP: algo=1 (RSA) fptype=2 (SHA256) + fp bytes
            52: b'\x03\x01\x01' + bytes(range(1, 21)),  # TLSA: usage=3 selector=1 mtype=1 + 20 bytes
            257: b'\x00\x05issueletsencrypt.org',  # CAA: flags=0 tag="issue" value
